'use strict';
const{test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=path.resolve(__dirname,'../..'),assets=process.env.BUILDING_CATEGORIES_ASSET_DIR||root,read=f=>fs.readFileSync(path.join(assets,f),'utf8'),proof=JSON.parse(fs.readFileSync(path.join(root,'outils/audits/I18N-BUILDING-CATEGORIES-20261116-preuve.json'))),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],snapshot=(sha,f)=>execFileSync('git',['show',sha+':'+f],{cwd:root,encoding:'utf8',maxBuffer:6e6}),old=f=>snapshot(proof.baseCommit,f);
function fn(s,name){const n=parse(s).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name===name);assert.ok(n,name);return s.slice(n.start,n.end);}
const catalogs=['i18n/resources.js','i18n/plateau-resources.js','i18n/toast-resources.js','i18n/character-sheet-resources.js','i18n/commerce-menu-resources.js','i18n/sovarka-justice-resources.js','i18n/navigation-resources.js'];
function load(reader){const c={RP_I18N_GAME_ENABLED:true};c.window=c;vm.createContext(c);for(const f of catalogs)vm.runInContext(reader(f),c);return c;}
const value=(c,lang,key)=>key.split('.').reduce((o,k)=>o?.[k],c.RP_I18N_RESOURCES[lang].translation);
test('58 catégories réelles : 53 textes/424 valeurs nouvelles, cinq ressources réutilisées, français intégral et noms propres conservés',()=>{
 const before=load(old),own=load(f=>snapshot(proof.codeCommit,f)),current=load(read);const c={};vm.createContext(c);vm.runInContext(old('data.js')+';this.W=WORLD;this.B=BUILDINGS;',c);const cats=[...new Set(Object.values(c.W).flatMap(cs=>Object.values(cs).flatMap(v=>(v.buildings||[]).map(id=>c.B[id]?.cat).filter(Boolean))))].sort();assert.deepEqual(cats,proof.categories.map(r=>r.fr).sort());assert.equal(cats.length,58);
 for(const l of langs){const a=JSON.parse(JSON.stringify(own.RP_I18N_RESOURCES[l].translation.navigation)),b=JSON.parse(JSON.stringify(before.RP_I18N_RESOURCES[l].translation.navigation));assert.equal(Object.keys(a).length-Object.keys(b).length,53);for(const r of proof.categories){assert.equal(current.RPNavigationI18n.categoryKey(r.fr),r.key);const t=value(current,l,r.key);assert.equal(typeof t,'string');assert.ok(t.trim());if(l==='fr')assert.equal(t,r.fr);if(r.reused)assert.equal(t,value(before,l,r.key));else{assert.equal(t,value(own,l,r.key));delete a[r.key.split('.')[1]];}for(const name of ['Papyrusisme','Cocaïsme','Tractorisme','Loukoumisme'])if(r.fr.includes(name))assert.ok(t.includes(name),name+'/'+l);}assert.deepEqual(a,b,l);}
 assert.equal(current.RPNavigationI18n.categoryKey('Catégorie inconnue'),null);assert.equal(current.RPNavigationI18n.categoryMarkup('Catégorie <inconnue>'),'Catégorie &lt;inconnue&gt;');
});
test('navigation identique hors seules écritures UI ; données, droits, commandes, coûts et paramètres inchangés',()=>{
 const own=snapshot(proof.codeCommit,'plateau-navigation.js');const restored=own.replace('  globalThis.RPI18nPlateau?.apply?.(grid);\n','').replace("  globalThis.RPNavigationI18n?.markCategory?.(document.getElementById('bat-cat'),displayCat);\n",'').replace('(globalThis.RPNavigationI18n?.categoryMarkup?.(b.cat) ?? b.cat)','b.cat').replace('>· <span data-i18n="toastTitles.restrictedAccess">Accès restreint</span></span>','>· Accès restreint</span>');assert.equal(restored,old('plateau-navigation.js'));
 const names=execFileSync('git',['diff','--name-only',proof.baseCommit,proof.codeCommit],{cwd:root,encoding:'utf8'}).trim().split('\n');assert.deepEqual(names.filter(f=>!['RELAIS.md','plateau-navigation.js','plateau.html','i18n/navigation-resources.js','i18n/packed/navigation-resources.js.br','outils/audits/I18N-CATALOGUES-TRANSPORT.json'].includes(f)),[]);
 for(const f of ['data.js','plateau-politique.js','plateau-core.js','plateau-commerce-pj.js','plateau-justice-economie.js','style.css','i18n/plateau-init.js'])assert.equal(snapshot(proof.codeCommit,f),old(f),f);
 const norm=s=>s.replace(/(plateau-navigation\.js|i18n\/navigation-resources\.js)\?v=[^"]+/g,'$1?v=VERSION');assert.equal(norm(snapshot(proof.codeCommit,'plateau.html')),norm(old('plateau.html')));
});
test('Chromium : 58 catégories, vrais bâtiments des quatre empires, neuf langues, 320/390/1280, RTL, verrous et clic normal conservés',async()=>{
 const{chromium}=require('playwright'),browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0,restricted=0;
 const nav=read('plateau-navigation.js'),base=old('plateau-navigation.js'),header=s=>{const body=fn(s,'enterBuilding'),a=body.indexOf('  const ctx = getBuildingContext(buildingId);'),b=body.indexOf('  // Pas de transparence',a);assert.ok(a>=0&&b>a);return body.slice(a,b);};
 try{for(const width of [320,390,1280]){const p=await browser.newPage({viewport:{width,height:800}}),errors=[],requests=[];p.on('pageerror',e=>errors.push(String(e)));await p.route('**/*',r=>{requests.push(r.request().url());return r.abort();});
 await p.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><div id="vue-batiment"><div class="batiment-header"><div class="batiment-header-info"><div id="bat-nom" class="batiment-nom"></div><div id="bat-cat" class="batiment-cat"></div></div></div></div><div id="minimap-grid" class="minimap-grid"></div><input id="draft" value="Brouillon intact"><div id="scroll" style="height:70px;overflow:auto"><div style="height:400px">Repère</div></div></body></html>');await p.addStyleTag({content:read('style.css')});await p.addScriptTag({content:read('i18n/i18next.min.js')});await p.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.state={country:'soviet',currentCity:'capitale',currentBuilding:'fixture',currentRoom:'fixture',char:{name:'Fixture'},pa:7,arg:1234,inventory:[{id:'intact'}],progression:{step:3}};window.calls=[];window.enterBuilding=(id)=>calls.push(['enterBuilding',id]);for(const n of ['fetch','sbRpc','sbRpcVerdict','payer_ordre','deduireCoutOrdre','doOrder'])window[n]=(...a)=>{calls.push([n,...a]);throw Error('Appel métier interdit');};window.stable=()=>JSON.stringify({state,calls,draft:document.getElementById('draft').value,focus:document.activeElement.id,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,scroll:document.getElementById('scroll').scrollTop});});
 await p.addScriptTag({content:read('data.js')});for(const f of catalogs)await p.addScriptTag({content:read(f)});await p.addScriptTag({content:read('i18n/plateau-init.js')});
 await p.addScriptTag({content:fn(nav,'getBuildingContext')+'\n'+fn(nav,'minimapCard')+'\n'+fn(nav,'renderMinimap')+'\n'+fn(base,'minimapCard').replace('function minimapCard(','function minimapCardOriginal(')+'\n'+fn(base,'renderMinimap').replace('function renderMinimap(','function renderMinimapOriginal(').replaceAll('minimapCard(','minimapCardOriginal(')+'\nfunction renderHeader(id){const buildingId=id,b=BUILDINGS[id];\n'+header(nav)+'\n}\nfunction renderHeaderOriginal(id){const buildingId=id,b=BUILDINGS[id];\n'+header(base)+'\n}'});
 const examples=await p.evaluate(()=>{const out=new Map();for(const[country,cities]of Object.entries(WORLD))for(const[city,v]of Object.entries(cities))for(const id of v.buildings||[]){const cat=BUILDINGS[id]?.cat;if(cat&&!out.has(cat))out.set(cat,{country,city,id,cat});}return [...out.values()];});assert.equal(examples.length,58);
 await p.evaluate(()=>{window.inspect=id=>{const card=[...document.querySelectorAll('.minimap-building')].find(n=>n.getAttribute('onclick')==="enterBuilding('"+id+"')");if(!card)throw Error('carte manquante '+id);return {cat:card.querySelector('.minimap-bld-cat').textContent,name:card.querySelector('.minimap-bld-name').textContent,persons:card.querySelector('.minimap-persons')?.textContent||'',onclick:card.getAttribute('onclick'),mouseenter:card.getAttribute('onmouseenter'),mouseleave:card.getAttribute('onmouseleave'),className:card.className,icon:card.querySelector('.minimap-bld-icon').innerHTML,locked:!!BUILDINGS[id].locked};};});
 for(const x of examples){const before=await p.evaluate(async x=>{await i18next.changeLanguage('en');state.country=x.country;state.currentCity=x.city;state.currentBuilding=x.id;renderHeaderOriginal(x.id);renderMinimapOriginal(x.city);const old=inspect(x.id);document.querySelectorAll('.minimap-building').forEach(n=>{if(n.getAttribute('onclick')===old.onclick)n.click();});const intent=calls.splice(0);return {old,intent,header:document.getElementById('bat-cat').textContent};},x);assert.equal(before.header,x.cat);assert.ok(before.old.cat.startsWith(x.cat));
 const start=await p.evaluate(x=>{renderHeader(x.id);renderMinimap(x.city);document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,6);document.getElementById('scroll').scrollTop=50;return {snapshot:stable(),card:inspect(x.id),header:document.getElementById('bat-cat').textContent};},x);assert.deepEqual({...start.card,cat:before.old.cat},before.old);const source=proof.categories.find(r=>r.fr===x.cat);assert.ok(source);if(before.old.locked)restricted++;
 for(const lang of langs){const got=await p.evaluate(async({lang,x,key})=>{await i18next.changeLanguage(lang);const node=document.querySelector('#bat-cat [data-i18n]'),card=inspect(x.id),expected=i18next.t(key);return {snapshot:stable(),header:node.textContent,expected,key:node.dataset.i18n,card,dir:node.dir,overflow:document.documentElement.scrollWidth>innerWidth,inside:node.parentElement.scrollWidth<=node.parentElement.clientWidth+1,restriction:RPToastI18n.label('Accès restreint')};},{lang,x,key:source.key});assert.equal(got.snapshot,start.snapshot,x.cat+'/'+lang);assert.equal(got.header,got.expected);assert.equal(got.key,source.key);assert.equal(got.card.cat,got.expected+' '+(got.card.locked?'· '+got.restriction:''));if(lang==='fr'){assert.equal(got.header,before.header);assert.equal(got.card.cat,before.old.cat);}assert.equal(got.dir,lang==='ar'?'rtl':'');assert.equal(got.overflow,false,x.cat+'/'+lang+'/'+width);assert.equal(got.inside,true,x.cat+'/'+lang+'/'+width);switches++;}
 const intent=await p.evaluate(x=>{calls.length=0;const n=[...document.querySelectorAll('.minimap-building')].find(n=>n.getAttribute('onclick')==="enterBuilding('"+x.id+"')");n.click();return calls.splice(0);},x);assert.deepEqual(intent,before.intent);}
 const fallback=await p.evaluate(async()=>{await i18next.changeLanguage('fr');RPNavigationI18n.markCategory(document.getElementById('bat-cat'),'Transport');const saved=JSON.parse(JSON.stringify(i18next.getResourceBundle('de','translation'))),missing=JSON.parse(JSON.stringify(saved));delete missing.navigation.categoryTransport;i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',missing);await i18next.changeLanguage('ar');const before=stable();await i18next.changeLanguage('de');const out={text:document.getElementById('bat-cat').textContent,same:stable()===before};i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',saved);return out;});assert.deepEqual(fallback,{text:'Transport',same:true});
 // Le catalogue courant n'a aucun flag b.locked : variante visuelle simulée, sans fichier de données modifié.
 const lockedFixture=await p.evaluate(async()=>{const id=state.currentBuilding,b=BUILDINGS[id],saved=b.locked;try{b.locked=true;renderMinimap(state.currentCity);const before=stable();for(const l of ['fr','ar','de']){await i18next.changeLanguage(l);const c=inspect(id);if(!c.cat.endsWith('· '+RPToastI18n.label('Accès restreint'))||stable()!==before)throw Error('restriction ou état modifié');}return true;}finally{if(saved===undefined)delete b.locked;else b.locked=saved;}});assert.equal(lockedFixture,true);restricted++;
 const guard=await p.evaluate(async()=>{await i18next.changeLanguage('ar');RPNavigationI18n.markCategory(document.getElementById('bat-cat'),'Catégorie <inconnue>');await i18next.changeLanguage('en');return {text:document.getElementById('bat-cat').textContent,images:document.getElementById('bat-cat').querySelectorAll('img').length,markers:document.getElementById('bat-cat').querySelectorAll('[data-i18n]').length};});assert.deepEqual(guard,{text:'Catégorie <inconnue>',images:0,markers:0});assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await p.close();}}finally{await browser.close();}assert.equal(switches,1566);assert.ok(restricted>0);console.log(switches+' bascules, '+restricted+' variantes de verrou visuel simulées, identifiants et clics inchangés.');
});
